    /** Inflated reference: [Y_SIZE] + 2 * [C_SIZE] bytes (Y, Cb, Cr). */
    val referencePlanes: ByteArray by lazy {
        val packed = Base64.getDecoder().decode(REFERENCE_BASE64.joinToString(""))
        val inf = java.util.zip.Inflater()
        inf.setInput(packed)
        val out = ByteArray(Y_SIZE + 2 * C_SIZE)
        var n = 0
        while (n < out.size && !inf.finished()) {
            val r = inf.inflate(out, n, out.size - n)
            if (r == 0 && (inf.needsInput() || inf.needsDictionary())) break
            n += r
        }
        inf.end()
        check(n == out.size) { "reference size" }
        out
    }
    val referenceY: ByteArray by lazy { referencePlanes.copyOfRange(0, Y_SIZE) }
    val referenceCb: ByteArray by lazy { referencePlanes.copyOfRange(Y_SIZE, Y_SIZE + C_SIZE) }
    val referenceCr: ByteArray by lazy { referencePlanes.copyOfRange(Y_SIZE + C_SIZE, Y_SIZE + 2 * C_SIZE) }
}
